/* eslint-disable max-len */

'use strict';

// FUNCTIONS //

/**
* Resolves an index into the input array.
*
* @private
* @param {NonNegativeInteger} a1 - first parameter
* @param {NonNegativeInteger} a2 - second parameter
* @param {NonNegativeInteger} a3 - third parameter
* @param {NonNegativeInteger} l1 - fourth parameter
* @param {NonNegativeInteger} ido - fifth parameter
* @param {NonNegativeInteger} offset - index offset
* @returns {NonNegativeInteger} index
*/
function iptr( a1, a2, a3, l1, ido, offset ) { // FIXME: update with more descriptive parameter descriptions
	return ( ( (a3*l1) + a2) * ido ) + a1 + offset; // FIXME: support strides
}

/**
* Resolves an index into the output array.
*
* @private
* @param {NonNegativeInteger} a1 - first parameter
* @param {NonNegativeInteger} a2 - second parameter
* @param {NonNegativeInteger} a3 - third parameter
* @param {NonNegativeInteger} ido - fourth parameter
* @param {NonNegativeInteger} offset - index offset
* @returns {NonNegativeInteger} index
*/
function optr( a1, a2, a3, ido, offset ) { // FIXME: update with more descriptive parameter descriptions
	return ( ( (a3*2) + a2) * ido ) + a1 + offset; // FIXME: support strides
}


// MAIN //

/**
* Performs the forward Fourier transform of length 2 for real-valued sequences.
*
* @private
* @param {NonNegativeInteger} ido - number of real values for each transform
* @param {NonNegativeInteger} l1 - length of the input sequences
* @param {Float64Array} cc - input array containing the sequences to be transformed
* @param {NonNegativeInteger} offsetCC - offset for `cc`
* @param {Float64Array} out - output array for storing transformed sequences
* @param {NonNegativeInteger} offsetOut - offset for `out`
* @param {Float64Array} twiddles - array containing twiddle factors
* @param {NonNegativeInteger} offsetT - index offset for `twiddles`
* @returns {void}
*/
function radf2( ido, l1, cc, offsetCC, out, offsetOut, twiddles, offsetT ) { // FIXME: support strides
	var idp2;
	var tr2;
	var ti2;
	var ip1;
	var ip2;
	var it1;
	var it2;
	var io;
	var ic;
	var i;
	var k;

	// Adjust offsets: // FIXME: why are these adjustments necessary? Describe here what is happening.
	offsetOut -= 1 + ( ido*3 );
	offsetCC -= 1 + ( ido*(1+l1) );

	// FIXME: describe what is happening below
	for ( k = 1; k <= l1; k++ ) {
		ip1 = iptr( 1, k, 1, l1, ido, offsetCC );
		ip2 = iptr( 1, k, 2, l1, ido, offsetCC );

		io = optr( 1, 1, k, ido, offsetOut );
		out[ io ] = cc[ ip1 ] + cc[ ip2 ];

		io = optr( ido, 2, k, ido, offsetOut );
		out[ io ] = cc[ ip1 ] - cc[ ip2 ];
	}
	// FIXME: describe why this check is necessary
	if ( ido < 2 ) {
		return;
	}
	if ( ido !== 2 ) {
		idp2 = ido + 2;

		// FIXME: describe what is happening in the loops below
		for ( k = 1; k <= l1; k++ ) {
			for ( i = 3; i <= ido; i += 2 ) {
				ic = idp2 - i;

				it1 = i - 2 + offsetT;
				it2 = i - 1 + offsetT;

				ip1 = iptr( i-1, k, 2, l1, ido, offsetCC );
				ip2 = iptr( i, k, 2, l1, ido, offsetCC );
				tr2 = ( twiddles[ it1 ] * cc[ ip1 ] ) + ( twiddles[ it2 ] * cc[ ip2 ] );
				ti2 = ( twiddles[ it1 ] * cc[ ip2 ] ) - ( twiddles[ it2 ] * cc[ ip1 ] );

				ip1 = iptr( i, k, 1, l1, ido, offsetCC );
				io = optr( i, 1, k, ido, offsetOut );
				out[ optr ] = cc[ ip1 ] + ti2;

				io = optr( ic, 2, k, ido, offsetOut );
				out[ io ] = ti2 - cc[ ip1 ];

				ip1 = iptr( i-1, k, 1, l1, ido, offsetCC );
				io = optr( i-1, 1, k, ido, offsetOut );
				out[ io ] = cc[ ip1 ] + tr2;

				io = optr( ic-1, 2, k, ido, offsetOut );
				out[ io ] = cc[ ip1 ] - tr2;
			}
		}
		// FIXME: explain why we are checking whether `ido` is odd
		if ( ido%2 === 1 ) {
			return;
		}
	}
	// FIXME: describe what is happening here
	for ( k = 1; k <= l1; k++ ) {
		ip1 = iptr( ido, k, 2, l1, ido, offsetCC );
		io = optr( 1, 2, k, ido, offsetOut );
		out[ io ] = -cc[ ip1 ];

		ip1 = iptr( ido, k, 1, l1, ido, offsetCC );
		io = optr( ido, 1, k, ido, offsetOut );
		out[ io ] = cc[ ip1 ];
	}
}


// EXPORTS //

module.exports = radf2;
